package com.changzheng.service;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.changzheng.common.BizException; import com.changzheng.dto.SaveUserInfoRequest; import com.changzheng.entity.User; import com.changzheng.mapper.UserMapper; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class UserService { private final UserMapper mapper; public User get(Long id){User u=mapper.selectById(id);if(u==null)throw new BizException(40002,"用户不存在");return u;} public User update(SaveUserInfoRequest r){User u=get(r.getUserId());u.setAvatarUrl(r.getAvatarUrl());u.setCity(r.getCity());u.setCountry(r.getCountry());u.setGender(r.getGender());u.setNickname(r.getNickname());u.setProvince(r.getProvince());u.setUpdatedAt(LocalDateTime.now());mapper.updateById(u);return u;} public int count(){return Math.toIntExact(mapper.selectCount(new QueryWrapper<>()));}}
